import{_ as t,o as a,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/36-过度敏感的依恋机制.md","filePath":"books/attached/36-过度敏感的依恋机制.md","lastUpdated":1794298621000}'),i={name:"books/attached/36-过度敏感的依恋机制.md"};function l(o,p,r,s,n,c){return a(),e("div",null,[...p[0]||(p[0]=[_('<h3 id="过度敏感的依恋机制" tabindex="-1">过度敏感的依恋机制 <a class="header-anchor" href="#过度敏感的依恋机制" aria-label="Permalink to &quot;过度敏感的依恋机制&quot;">​</a></h3><p>然而，艾米莉并不是受虐狂或患有边缘型人格障碍。她单纯只是个依恋机制被激活的个案。像艾米莉一样带有焦虑型依恋风格的人，拥有过度敏感的依恋机制。正如我们前文所提到的，依恋机制存在于我们的大脑，其职责是追踪和监测我们依恋对象的安全性与存在感。若你是焦虑型依恋风格，那你就具备了一种独特的感受力，能感受到亲密关系所受到的威胁。即使是一点细微的异样线索，也会激活你的依恋机制。而机制一旦激活，除非你伴侣给你一个确切的反馈，表明自己对你别无二心，以及你们的关系绝对可靠，否则你根本无法平静下来。然而，伴侣却往往根本无法像焦虑型依恋者们一样，如此明敏地感知到所有细节。</p><p>若要阐释那些带有焦虑型依恋风格的人究竟有多敏感，伊利诺伊大学香槟分校的研究者克里斯·弗雷利的实验室团队进行了一项研究。在这项研究中，他们发现了一种独特的方法，用以测量焦虑型依恋风格对于社交线索的警觉性。他们采用了一种“形变电影”（morph movie）技术——这是一种经过电脑处理的影片，片中有一张脸，一开始呈现出带有特定情绪的表情，而后这个表情渐渐转变成中性。实验的被试接受的要求是这样的，在他们感觉画面中原始的情绪消失时，需要将画面暂停。实验发现，带有焦虑型依恋风格的人，倾向于比其他人更早地察觉到情绪的消解。同样地，若是任务颠倒过来——画面始于中性表情，而逐渐变为情绪鲜明的表情，相对更焦虑的个体也会更早地察觉到情绪的产生。这项发现表明，带有焦虑型依恋风格的人，确实是对于他人的情绪化表现更加警觉，并且对他人的线索有着更高水平的精准度与敏感性。然而，这项发现也同时昭示了一种警告。研究表明，焦虑型依恋风格的人倾向于过早得出定论，而一旦如此，他们往往容易误解他人的情绪状态。只有当实验变换一种方式设置，即焦虑型依恋的被试必须在做出判断之前等待更长的时间、获得更多的信息时，他们相较于其他被试才有所优势。对于焦虑型依恋的人群，这里有一条重要忠告：在你产生反应或是过早下定论之前，但凡是多等一秒，你都会获得一种解密周遭世界的超能力，并且利用之汲取优势。但若是鲁莽行事，你便会处处做些错误判断，从而伤害到自己。</p><p>那些呈现出焦虑型依恋风格的人们，会比其他人更迅速地进入一种敏锐的激活状态——他们对自己周遭的世界，有着事无巨细的洞察力，比如说他们很容易从伴侣的肢体语言中，察觉到消极与抗拒。一旦得以激活，他们常常沉醉于一种思考之中，其思考的目的只有一个：那就是重塑自己与伴侣之间的亲密关系。这种思考也就是激活策略（activating strategies）。</p><p>激活策略涵盖了一切迫使你获取与伴侣间的亲密关系的想法或感受，无论是生理还是心理层面的。当你的伴侣做出某种回应，而这种回应一定程度上使你们重修旧好。这时候，你便会重拾那个冷静的常态自我。</p><p>激活策略</p><p>那些迫使你去追寻与伴侣的亲密关系的想法与感受：</p><ul><li><p>你的伴侣在脑子里挥之不去，以至于难以对别的事情集中注意。</p></li><li><p>只记得他们的优点。</p></li><li><p>极度崇拜他们，高估他们的才华与能力并且妄自菲薄。</p></li><li><p>只有在与他们产生联系时，焦虑感才会暂且消失。</p></li><li><p>坚信他们是你的唯一挚爱，比如说：</p></li></ul><p>◎“我本来就没什么合得来的人——又怎么可能再找到一个跟他一样的人呢？”</p><p>◎“遇到一个新的朋友得花上若干年，我会孤独终老的。”</p><ul><li>坚信即使你在这段关系里并不开心，也不应该放手，比如说：</li></ul><p>◎“她离开我以后，一定会变成一个更好的伴侣——不过那可就是别人的了。”</p><p>◎“他会有所改变的。”</p><p>◎“每对伴侣都是有点问题的——这样看来，我们也没什么特别的。”</p><p>在艾米莉这个案例中，她的依恋机制就非常典型了。在他们相爱期间，艾米莉发现在自己工作时，大卫看了好几小时色情片，还骗她说自己是去试镜了。她还发现他在网上，穿梭于不同聊天室，跟别的女孩调情（当然也包括艾米莉自己化名的那个）。然而她还是很难与他了断，她被各种激活策略轮番轰炸，这些策略与我们上面所提如出一辙：想着他会有所改观；想着每个人都有自己的问题，诸如此类。她花了一年多的时间，才鼓起勇气斩断这段关系。在这段时间以及分手以后的相当一阵子，她在分析中，访谈的内容绝大多数是关于他的。直到几年以后，她嫁给了一个很不错的人，这才重拾那个原来的自我，她带着疑惑回顾了那一整段经历。她也根本不敢相信自己花费了那么多时间来进行临床精神分析，而分析的对象，则是那段关系之中自己“狂热”行为的深层根源，也就是那个男人。若是她快些遇见一位好人——这个人不会持续地激起她的依恋机制——那么她早就可以从对自己“边缘性受虐狂人格特质”的无谓挣扎之中解脱出来了。</p>',15)])])}const h=t(i,[["render",l]]);export{m as __pageData,h as default};
